def source(record_id, title, publisher, source_kind, url, supports, scope, limitations=()):
    return {
        "record_id": record_id,
        "record_kind": "source_evidence",
        "edition": EDITION,
        "status": "verified",
        "title": title,
        "publisher": publisher,
        "source_kind": source_kind,
        "url": url,
        "supports": list(supports),
        "authority_scope": scope,
        "limitations": list(limitations) or ["Primary evidence for its stated jurisdiction and purpose; local implementations and editions may differ."],
        "accessed_at": ACCESSED,
    }


