def case(sector, slug, subindustries, name, modes, question, action, unit, systems, shapes, methods, operations, inputs, outputs, evidence, failures=(), limitations=(), llm="none"):
    d = SECTOR_DEFAULTS[sector]
    return {
        "record_id": f"case.{sector}.{slug}",
        "record_kind": "analytical_case",
        "edition": EDITION,
        "status": "sourced_candidate",
        "industry_id": d["industry"],
        "subindustry_ids": subindustries,
        "name": name,
        "analytical_modes": modes,
        "sovereign_question": question,
        "decision_or_action": action,
        "actors": d["actors"],
        "unit_of_analysis": unit,
        "population": d["population"],
        "grain": unit,
        "time_model": d["time"],
        "source_system_refs": systems,
        "data_shape_refs": shapes,
        "data_type_refs": ["datatype.identifier.scoped", "datatype.time.interval", "datatype.quantity.qualified", "datatype.category.versioned", "datatype.uncertainty.estimate"],
        "method_refs": methods,
        "operation_refs": operations,
        "inputs": inputs,
        "outputs": outputs,
        "assumptions": d["assumptions"],
        "invariants": d["invariants"],
        "failure_modes": d["failures"] + list(failures),
        "evidence_refs": evidence,
        "llm_dependency": llm,
        "limitations": d["limitations"] + list(limitations),
        "sensitive_use": sector in {"safety", "justice", "social", "education", "nonprofit"},
        "human_review_required": sector in {"safety", "justice", "social", "education", "nonprofit"},
    }


