def write_jsonl(name, rows):
    path = ROOT / name
    payload = "".join(json.dumps(row, sort_keys=True, separators=(",", ":")) + "\n" for row in rows)
    path.write_text(payload, encoding="utf-8")


def validate_local():
    all_ids = [r["record_id"] for r in SOURCES + SYSTEMS + SHAPES + CASES]
    dupes = [k for k, v in Counter(all_ids).items() if v > 1]
    if dupes:
        raise SystemExit(f"duplicate ids: {dupes}")
    source_ids = {r["record_id"] for r in SOURCES}
    system_ids = {r["record_id"] for r in SYSTEMS}
    shape_ids = {r["record_id"] for r in SHAPES}
    for row in SYSTEMS + SHAPES + CASES:
        missing = set(row["evidence_refs"]) - source_ids
        if missing:
            raise SystemExit(f"{row['record_id']} missing evidence refs: {sorted(missing)}")
    for row in CASES:
        missing_systems = set(row["source_system_refs"]) - system_ids
        missing_shapes = set(row["data_shape_refs"]) - shape_ids
        if missing_systems or missing_shapes:
            raise SystemExit(f"{row['record_id']} missing systems={sorted(missing_systems)} shapes={sorted(missing_shapes)}")
    by_sector = Counter(r["record_id"].split(".")[1] for r in CASES)
    if len(SOURCES) < 25 or min(by_sector.values()) < 10:
        raise SystemExit(f"coverage floor failed: sources={len(SOURCES)} sectors={dict(by_sector)}")


def main():
    validate_local()
    write_jsonl("sources.jsonl", SOURCES)
    write_jsonl("source-systems.jsonl", SYSTEMS)
    write_jsonl("data-shapes.jsonl", SHAPES)
    write_jsonl("analytics-cases.jsonl", CASES)
    print(json.dumps({
        "sources": len(SOURCES),
        "source_systems": len(SYSTEMS),
        "data_shapes": len(SHAPES),
        "analytical_cases": len(CASES),
        "cases_by_sector": dict(sorted(Counter(r["record_id"].split(".")[1] for r in CASES).items())),
    }, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()
